INSERT INTO `cache` VALUES ('vinh-phu-cache-ai_chat_knowledge_cached_at','s:19:\"20/04/2026 15:11:08\";',1776676268),('vinh-phu-cache-ai_chat_sheet_company','s:10193:\"- Tên cty: Vinh Phú\n- Số nhân viên: Hơn 150 người\n- Phòng ban: Kế toán, Kinh doanh, Công nhân, vv...\n- Giới thiệu cty: I. Thư ngỏ\n\n CÔNG TY CỔ PHẦN TẬP ĐOÀN VINH PHÚ xin gửi lời chào chân trọng, lời chúc sức khỏe, thành công và hạnh phúc cùng lời cảm ơn chân thành tới toàn thể Quý khách hàng, Quý đối tác đã luôn tin tưởng, ủng hộ và đồng hành với chúng tôi trong suốt thời gian qua.\n\nTrải qua gần 20 năm xây dựng và phát triển, Vinh Phú Group không ngừng nâng cao vị thế của mình và tự hào là Công ty hàng đầu trong lĩnh vực sản xuất và kinh doanh nguyên vật liệu xây dựng, đặc biệt là: Vật liệu cách âm cách nhiệt bảo ôn (Bông thủy tinh, Cách nhiệt VIP foam crosslink, Tú khí Air bubble…), Vật liệu bảo ôn ống đồng PE Foam – Cao su lưu hoá Mflex, Giấy bạc dập hoa văn ứng dụng trong sản xuất tôn xốp PU cách nhiệt, Màng PVC film in vân gỗ ứng dụng trong sản xuất tấm ốp Nano – sàn SPC, Tấm ốp than tre đa năng, Vít bắn tôn cao cấp mạ Nano nhôm kẽm, Vải PP chống thấm,…\n\nVới đội ngũ cán bộ, công nhân viên làm việc tâm huyết, nhiệt tình, trình độ chuyên môn cao cùng với sự đầu tư lớn về công nghệ sản xuất, các sản phẩm của Công ty đã có mặt ở rất nhiều nhà máy sản xuất tôn xốp PU, nhà máy sản xuất tấm ốp Nano PVC panel lớn khắp cả nước và trên thế giới, cũng như rất nhiều công trình nhà máy lớn đang sử dụng sản phẩm của công ty chúng tôi.\n\nTrong suất quá trình hoạt động, Công ty chúng tôi đã không ngừng đổi mới, nâng cao chất lượng sản phẩm và dịch vụ, sẵn sàng đáp ứng mọi yêu cầu cao nhất của Quý khách hàng, Quý đối tác với phương châm mục tiêu “sản xuất ra sản phẩm có giá trị cao để tạo được niềm tin với khách hàng”, xem lợi ích của khách hàng, người tiêu dùng là tiêu chí thành công của Công ty.\n\nCông ty cổ phần tập đoàn Vinh Phú sẵn sàng đồng hành và mong muốn tiếp tục nhận được sự quan tâm, tin tưởng, ủng hộ nhiệt tình và hợp tác của Quý khách hàng, Quý đối tác để có thể tạo ra những sản phẩm hoàn hảo có giá trị vượt thời gian.\n\nCông ty cổ phần tập đoàn Vinh Phú luôn sẵn sàng và mong muốn hợp tác với Quý khách hàng, Quý đối tác lâu dài và bền vững.\n\nTrân trọng!\n- Lịch sử: Hiện nay công ty không ngừng mở rộng nhà máy, đào tạo các kỹ sư lành nghề có trình độ cao, đầu tư các dây truyền công nghệ hiện đại và tân tiến nhất. Áp dụng công nghệ AI vào hoạt động sản xuất kinh doanh để cho ra đời những sản phẩm – dịch vụ mang lại giá trị cao, tạo được niềm tin với khách hàng trong và ngoài nước.\n\nNăm 2023: Sau nhiều năm nhập khẩu, thương mại sản phẩm PVC film in vân gỗ, vân đá cho lĩnh vực sản xuất tấm ốp Nano panel và sàn nhựa SCP, công ty đã chính thức sản xuất thành công sản phẩm này tại khu công nghiệp Đại Đồng mở rộng – Tiên Du – Bắc Ninh với diện tích nhà máy 12,000m2. Cùng năm 2023 công ty cũng đã chính thức thành lập nhà máy sản xuất giấy bạc khu vực phía Nam với diện tích 4500m2 tại cụm Công nghiệp Bình Chánh – Phường Khánh Bình – Thành Phố Tân Uyên – Bình Dương.\n\nNăm 2021: Sau nhiều năm nghiên cứu và không ngừng đầu tư trang thiết bị hiện đại và tân tiến Công ty đã sản xuất thành công ống bảo ôn xốp kéo cho ống điều hoà gia đình thương hiệu V-Tube. Tự hào là đơn vị cung cấp ống bảo ôn điều hoà cho toàn bộ hệ thống Điện máy xanh và Mediamart.\n\nNăm 2018: Công ty TNHH công nghệ mới Vinh Phú chính thức đổi tên thành Công ty cổ phần tập đoàn Vinh Phú với 4 cổ đông đều là những cá nhân xuất sắc gắn bó từ đầu thời kỳ mới thành lập. Cũng trong năm đó vào ngày 20/12/2018 Công ty có nhà máy mới đầu tiên cho riêng mình với diện tích 6,000m2 tại Khu công nghiệp Đại Đồng – Tân Hồng – Từ Sơn – Bắc Ninh.\n\nNăm 2015: Sau nhiều năm nhập khẩu và thương mại sản phẩm giấy bạc phục vụ cho lĩnh vực sản xuất tôn xốp cách nhiệt PU Foam. Một buổi chiều mưa gió ban lãnh đạo Công ty Vinh Phú đã phát minh ra sản phẩm Giấy bạc dập vân hoa (Aluminum foil Embossing) hiệu quả và tối ưu tuyệt đối. Cuối năm đó, Công ty chính thức nhập công nghệ hiện đại và tiên tiến để sản xuất sản phẩm này tại nhà xưởng số 134 Phố Đức Giang – Long Biên – Hà Nội.\n\nNăm 2012: Công ty ký hợp đồng hợp tác với Công ty SEOWKANG – Hàn Quốc mở nhà máy sản xuất tấm bảo ôn cách nhiệt PE – OPP tại Cum công nghiệp Đông Mỹ – Thanh Trì – Hà Nội.\n\nNăm 2010: Tự hào, trân trọng khi được chủ đầu từ Vingroup tin tưởng giao nhiệm vụ cung cấp và thi công hạn mục đá marble Thanh Hoá cho công trình Đàn Nam Giao trên tầng thượng Tháp C trung tâm thương mại Vincom Bà Triệu – Hà Nội. Cùng năm đó Công ty đã chính thức ký hợp đồng với Công ty Vinaconex E&C cung cấp đá marble cho quảng trường tòa nhà thương mại SPLENDORA An Khánh – Hà Nội với diện tích 10.000m²\n\nNăm 2008: Công ty Vinh Phú gây dấu ấn đầu tiên khi cung cấp thành công gói thầu sứ cách điện đường dây truyền tải điện 110 KW cho nhà máy thủy điện Cửa Đạt – Thanh Hóa, và cùng trong năm đó chính thức ký hợp đồng hợp tác toàn diện với Công ty Tôn Siam Viet Nam Steel – Chi nhánh của Công ty Okaya & Co., Ltd. (Okaya) – Nhật Bản tại Việt Nam cung cấp sản phẩm cách nhiệt bông thủy tinh, cách nhiệt VIP foam crosslink, cách nhiệt túi khí cho các nhà máy Nhật Bản đầu tư tại Việt Nam.\n\nNăm 2005: Xuất phát từ những ngày đầu với 2 cá nhân trẻ tuổi đầy nhiệt huyết và đam mê khởi nghiệp vượt khó, đam mê công nghệ. Với ý chí quyết tâm đóng góp một phần nhỏ cho sự phát triển chung của xã hội, từ đó Công ty TNHH Công nghệ mới Vinh Phú đã được thành lập với số vốn góp ban đầu là 20.000.000 VNĐ\n- TẦM NHÌN – SỨ MỆNH – GIÁ TRỊ CỐT LÕI: 1. TẦM NHÌN  \n\nTrở thành doanh nghiệp số một trong lĩnh vực sản xuất Nguyên vật liệu giấy bạc dập vân hoa cho ngành sản xuất tôn cách nhiệt xốp PU, nguyên liệu màng PVC Film cho ngành sản xuất tấm ốp Nano panel và sàn SPC đẳng cấp thế giới.\n\nTrở thành doanh nghiệp hàng đầu trong lĩnh vực cung cấp vật liệu cách nhiệt bảo ôn cho các nhà máy nước ngoài đầu tư tại Việt Nam.\n\n2. SỨ MỆNH\n\nTạo ra sản phẩm và dịch vụ có giá trị cao nhất nhằm giữ vững niềm tin với khách hàng. Lấy kim chỉ nam “Giá trị tạo niềm tin” trong xuyên xuất mọi hoạt động của công ty.\n\nXây dựng mối quan hệ tin cậy, uy tín, hợp tác cùng chiến thắng, hạnh phúc và cùng nhau phát triển bền vững.\n\nLuôn ý thức lợi ích của Vinh Phú Group luôn luôn gắn liền với lợi ích xã hội và những hoạt động đóng góp cho xã hội là một phần trách nhiệm của Vinh Phú đối với cộng đồng.\n\n3. GIÁ TRỊ CỐT LÕI\n\nVăn hoá Doanh nghiệp -Giá trị của Công ty dựa trên tinh thần làm việc và trách nhiệm kết hợp tinh thần Đại đoàn kết hỗ trợ lẫn nhau của các thành viên trong công ty, tạo thành khối thống nhất giúp chúng tôi không ngừng sáng tạo và phát triển.\n\nTriết lý trong tổ chức, quản lý và phát triển trong hoạt động kinh doanh : Lấy khách hàng là trung tâm, đầu tư phát triển nhân lực và tăng trưởng bền vững.\n- CƠ CẤU TỔ CHỨC CỦA CÔNG TY CỔ PHẦN TẬP ĐOÀN VINH PHÚ: Công ty Cổ phần Tập đoàn Vinh Phú có cơ cấu tổ chức theo phương thức lãnh đạo trực tuyến.\n\nCơ cấu tổ chức bộ máy hoạt động của Công ty theo sơ đồ sau:\n\nGIÁM ĐỐC\n\nGiám đốc Nhà máy\n\nBộ phận Kế hoạch\n\nTổ SX 1\n\nTổ SX 2\n\nTổ SX 3\n\nBộ phận Vận tải\n\nGiám đốc Kinh doanh\n\nPhòng Marketing & CSKH\n\nPhòng Kinh doanh\n\nNhóm 1\n\nNhóm 2\n\nNhóm 3\n\nPhòng Hành chính Tổng hợp\n\nPhòng Vật tư\n\nKế toán trưởng\n\nKế toán Nhà máy\n\nKế toán Tổng hợp\n- QUY MÔ CÔNG TY: Trụ sở công ty: Diện tích 800 m2 tại tầng 2&3 tòa nhà VIP số 352 Giải Phóng – Thanh Xuân – Hà Nội\n\nNhà máy số 1: Diện tích 6,000 m2 tại Lô J4-3 Khu công nghiệp Đại Đồng – Phường Tân Hồng – Từ Sơn – Bắc Ninh\n\nNhà máy số 2: Diện tích 4,500 m2 tại cụm công nghiệp Khánh Bình – Phường Khánh Bình – TP Tân Uyên – Tỉnh Bình Dương\n\nNhà máy số 3: Diện tích 12,000 m2 tại Lô CN1-2-2A Khu công nghiệp Đại Đồng 2 – Tiên Du – Bắc Ninh\n\nNhân sự: 300 nhân sự với 10% trình độ thạc sỹ, 30% trình độ đại học, 30% trình độ cao đẳng nghề và 30% trình độ THPT\n\nNăng lực sản xuất: 100,000,000 đơn vị sản phẩm/năm\n\nThị trường chính: Việt Nam và các nước trong khối ASEAN\n- Số điện thoại và email: 0946.286.186 - 0946.286.186\nvip@vinhphu.com.vn\";',1776676251),('vinh-phu-cache-ai_chat_sheet_guide','s:609:\"- Cập nhật danh sách mail: B1: Vào sheet update danh sách mail\nB2: Vào danh sách cơ sở nhấn vào danh sách Danh sách email > Sửa danh sách email > Đồng bộ từ sheet\n- Gửi mail tính lương: B1: Cập nhật danh sách email > File theo cơ sở > Ấn nút Upload file > Chọn file Google Sheets  > Ấn Upload file \nB2: Chỉnh sửa File Lương > Kiểm tra PDF (thử người đầu, người cuối, người giữa) > Tạo nhiều file PDF theo danh sách > Đợi 3 4p > Lịch sử xuất PDF hàng loạt > Gửi Email (Gửi 30 người 1 lúc thôi không nó hẹo)\";',1776676252),('vinh-phu-phong-hcns-cache-ai_chat_knowledge_cached_at','s:19:\"11/03/2026 07:26:07\";',1773217567),('vinh-phu-phong-hcns-cache-ai_chat_sheet_company','s:10193:\"- Tên cty: Vinh Phú\n- Số nhân viên: Hơn 150 người\n- Phòng ban: Kế toán, Kinh doanh, Công nhân, vv...\n- Giới thiệu cty: I. Thư ngỏ\n\n CÔNG TY CỔ PHẦN TẬP ĐOÀN VINH PHÚ xin gửi lời chào chân trọng, lời chúc sức khỏe, thành công và hạnh phúc cùng lời cảm ơn chân thành tới toàn thể Quý khách hàng, Quý đối tác đã luôn tin tưởng, ủng hộ và đồng hành với chúng tôi trong suốt thời gian qua.\n\nTrải qua gần 20 năm xây dựng và phát triển, Vinh Phú Group không ngừng nâng cao vị thế của mình và tự hào là Công ty hàng đầu trong lĩnh vực sản xuất và kinh doanh nguyên vật liệu xây dựng, đặc biệt là: Vật liệu cách âm cách nhiệt bảo ôn (Bông thủy tinh, Cách nhiệt VIP foam crosslink, Tú khí Air bubble…), Vật liệu bảo ôn ống đồng PE Foam – Cao su lưu hoá Mflex, Giấy bạc dập hoa văn ứng dụng trong sản xuất tôn xốp PU cách nhiệt, Màng PVC film in vân gỗ ứng dụng trong sản xuất tấm ốp Nano – sàn SPC, Tấm ốp than tre đa năng, Vít bắn tôn cao cấp mạ Nano nhôm kẽm, Vải PP chống thấm,…\n\nVới đội ngũ cán bộ, công nhân viên làm việc tâm huyết, nhiệt tình, trình độ chuyên môn cao cùng với sự đầu tư lớn về công nghệ sản xuất, các sản phẩm của Công ty đã có mặt ở rất nhiều nhà máy sản xuất tôn xốp PU, nhà máy sản xuất tấm ốp Nano PVC panel lớn khắp cả nước và trên thế giới, cũng như rất nhiều công trình nhà máy lớn đang sử dụng sản phẩm của công ty chúng tôi.\n\nTrong suất quá trình hoạt động, Công ty chúng tôi đã không ngừng đổi mới, nâng cao chất lượng sản phẩm và dịch vụ, sẵn sàng đáp ứng mọi yêu cầu cao nhất của Quý khách hàng, Quý đối tác với phương châm mục tiêu “sản xuất ra sản phẩm có giá trị cao để tạo được niềm tin với khách hàng”, xem lợi ích của khách hàng, người tiêu dùng là tiêu chí thành công của Công ty.\n\nCông ty cổ phần tập đoàn Vinh Phú sẵn sàng đồng hành và mong muốn tiếp tục nhận được sự quan tâm, tin tưởng, ủng hộ nhiệt tình và hợp tác của Quý khách hàng, Quý đối tác để có thể tạo ra những sản phẩm hoàn hảo có giá trị vượt thời gian.\n\nCông ty cổ phần tập đoàn Vinh Phú luôn sẵn sàng và mong muốn hợp tác với Quý khách hàng, Quý đối tác lâu dài và bền vững.\n\nTrân trọng!\n- Lịch sử: Hiện nay công ty không ngừng mở rộng nhà máy, đào tạo các kỹ sư lành nghề có trình độ cao, đầu tư các dây truyền công nghệ hiện đại và tân tiến nhất. Áp dụng công nghệ AI vào hoạt động sản xuất kinh doanh để cho ra đời những sản phẩm – dịch vụ mang lại giá trị cao, tạo được niềm tin với khách hàng trong và ngoài nước.\n\nNăm 2023: Sau nhiều năm nhập khẩu, thương mại sản phẩm PVC film in vân gỗ, vân đá cho lĩnh vực sản xuất tấm ốp Nano panel và sàn nhựa SCP, công ty đã chính thức sản xuất thành công sản phẩm này tại khu công nghiệp Đại Đồng mở rộng – Tiên Du – Bắc Ninh với diện tích nhà máy 12,000m2. Cùng năm 2023 công ty cũng đã chính thức thành lập nhà máy sản xuất giấy bạc khu vực phía Nam với diện tích 4500m2 tại cụm Công nghiệp Bình Chánh – Phường Khánh Bình – Thành Phố Tân Uyên – Bình Dương.\n\nNăm 2021: Sau nhiều năm nghiên cứu và không ngừng đầu tư trang thiết bị hiện đại và tân tiến Công ty đã sản xuất thành công ống bảo ôn xốp kéo cho ống điều hoà gia đình thương hiệu V-Tube. Tự hào là đơn vị cung cấp ống bảo ôn điều hoà cho toàn bộ hệ thống Điện máy xanh và Mediamart.\n\nNăm 2018: Công ty TNHH công nghệ mới Vinh Phú chính thức đổi tên thành Công ty cổ phần tập đoàn Vinh Phú với 4 cổ đông đều là những cá nhân xuất sắc gắn bó từ đầu thời kỳ mới thành lập. Cũng trong năm đó vào ngày 20/12/2018 Công ty có nhà máy mới đầu tiên cho riêng mình với diện tích 6,000m2 tại Khu công nghiệp Đại Đồng – Tân Hồng – Từ Sơn – Bắc Ninh.\n\nNăm 2015: Sau nhiều năm nhập khẩu và thương mại sản phẩm giấy bạc phục vụ cho lĩnh vực sản xuất tôn xốp cách nhiệt PU Foam. Một buổi chiều mưa gió ban lãnh đạo Công ty Vinh Phú đã phát minh ra sản phẩm Giấy bạc dập vân hoa (Aluminum foil Embossing) hiệu quả và tối ưu tuyệt đối. Cuối năm đó, Công ty chính thức nhập công nghệ hiện đại và tiên tiến để sản xuất sản phẩm này tại nhà xưởng số 134 Phố Đức Giang – Long Biên – Hà Nội.\n\nNăm 2012: Công ty ký hợp đồng hợp tác với Công ty SEOWKANG – Hàn Quốc mở nhà máy sản xuất tấm bảo ôn cách nhiệt PE – OPP tại Cum công nghiệp Đông Mỹ – Thanh Trì – Hà Nội.\n\nNăm 2010: Tự hào, trân trọng khi được chủ đầu từ Vingroup tin tưởng giao nhiệm vụ cung cấp và thi công hạn mục đá marble Thanh Hoá cho công trình Đàn Nam Giao trên tầng thượng Tháp C trung tâm thương mại Vincom Bà Triệu – Hà Nội. Cùng năm đó Công ty đã chính thức ký hợp đồng với Công ty Vinaconex E&C cung cấp đá marble cho quảng trường tòa nhà thương mại SPLENDORA An Khánh – Hà Nội với diện tích 10.000m²\n\nNăm 2008: Công ty Vinh Phú gây dấu ấn đầu tiên khi cung cấp thành công gói thầu sứ cách điện đường dây truyền tải điện 110 KW cho nhà máy thủy điện Cửa Đạt – Thanh Hóa, và cùng trong năm đó chính thức ký hợp đồng hợp tác toàn diện với Công ty Tôn Siam Viet Nam Steel – Chi nhánh của Công ty Okaya & Co., Ltd. (Okaya) – Nhật Bản tại Việt Nam cung cấp sản phẩm cách nhiệt bông thủy tinh, cách nhiệt VIP foam crosslink, cách nhiệt túi khí cho các nhà máy Nhật Bản đầu tư tại Việt Nam.\n\nNăm 2005: Xuất phát từ những ngày đầu với 2 cá nhân trẻ tuổi đầy nhiệt huyết và đam mê khởi nghiệp vượt khó, đam mê công nghệ. Với ý chí quyết tâm đóng góp một phần nhỏ cho sự phát triển chung của xã hội, từ đó Công ty TNHH Công nghệ mới Vinh Phú đã được thành lập với số vốn góp ban đầu là 20.000.000 VNĐ\n- TẦM NHÌN – SỨ MỆNH – GIÁ TRỊ CỐT LÕI: 1. TẦM NHÌN  \n\nTrở thành doanh nghiệp số một trong lĩnh vực sản xuất Nguyên vật liệu giấy bạc dập vân hoa cho ngành sản xuất tôn cách nhiệt xốp PU, nguyên liệu màng PVC Film cho ngành sản xuất tấm ốp Nano panel và sàn SPC đẳng cấp thế giới.\n\nTrở thành doanh nghiệp hàng đầu trong lĩnh vực cung cấp vật liệu cách nhiệt bảo ôn cho các nhà máy nước ngoài đầu tư tại Việt Nam.\n\n2. SỨ MỆNH\n\nTạo ra sản phẩm và dịch vụ có giá trị cao nhất nhằm giữ vững niềm tin với khách hàng. Lấy kim chỉ nam “Giá trị tạo niềm tin” trong xuyên xuất mọi hoạt động của công ty.\n\nXây dựng mối quan hệ tin cậy, uy tín, hợp tác cùng chiến thắng, hạnh phúc và cùng nhau phát triển bền vững.\n\nLuôn ý thức lợi ích của Vinh Phú Group luôn luôn gắn liền với lợi ích xã hội và những hoạt động đóng góp cho xã hội là một phần trách nhiệm của Vinh Phú đối với cộng đồng.\n\n3. GIÁ TRỊ CỐT LÕI\n\nVăn hoá Doanh nghiệp -Giá trị của Công ty dựa trên tinh thần làm việc và trách nhiệm kết hợp tinh thần Đại đoàn kết hỗ trợ lẫn nhau của các thành viên trong công ty, tạo thành khối thống nhất giúp chúng tôi không ngừng sáng tạo và phát triển.\n\nTriết lý trong tổ chức, quản lý và phát triển trong hoạt động kinh doanh : Lấy khách hàng là trung tâm, đầu tư phát triển nhân lực và tăng trưởng bền vững.\n- CƠ CẤU TỔ CHỨC CỦA CÔNG TY CỔ PHẦN TẬP ĐOÀN VINH PHÚ: Công ty Cổ phần Tập đoàn Vinh Phú có cơ cấu tổ chức theo phương thức lãnh đạo trực tuyến.\n\nCơ cấu tổ chức bộ máy hoạt động của Công ty theo sơ đồ sau:\n\nGIÁM ĐỐC\n\nGiám đốc Nhà máy\n\nBộ phận Kế hoạch\n\nTổ SX 1\n\nTổ SX 2\n\nTổ SX 3\n\nBộ phận Vận tải\n\nGiám đốc Kinh doanh\n\nPhòng Marketing & CSKH\n\nPhòng Kinh doanh\n\nNhóm 1\n\nNhóm 2\n\nNhóm 3\n\nPhòng Hành chính Tổng hợp\n\nPhòng Vật tư\n\nKế toán trưởng\n\nKế toán Nhà máy\n\nKế toán Tổng hợp\n- QUY MÔ CÔNG TY: Trụ sở công ty: Diện tích 800 m2 tại tầng 2&3 tòa nhà VIP số 352 Giải Phóng – Thanh Xuân – Hà Nội\n\nNhà máy số 1: Diện tích 6,000 m2 tại Lô J4-3 Khu công nghiệp Đại Đồng – Phường Tân Hồng – Từ Sơn – Bắc Ninh\n\nNhà máy số 2: Diện tích 4,500 m2 tại cụm công nghiệp Khánh Bình – Phường Khánh Bình – TP Tân Uyên – Tỉnh Bình Dương\n\nNhà máy số 3: Diện tích 12,000 m2 tại Lô CN1-2-2A Khu công nghiệp Đại Đồng 2 – Tiên Du – Bắc Ninh\n\nNhân sự: 300 nhân sự với 10% trình độ thạc sỹ, 30% trình độ đại học, 30% trình độ cao đẳng nghề và 30% trình độ THPT\n\nNăng lực sản xuất: 100,000,000 đơn vị sản phẩm/năm\n\nThị trường chính: Việt Nam và các nước trong khối ASEAN\n- Số điện thoại và email: 0946.286.186 - 0946.286.186\nvip@vinhphu.com.vn\";',1773217567),('vinh-phu-phong-hcns-cache-ai_chat_sheet_guide','s:609:\"- Cập nhật danh sách mail: B1: Vào sheet update danh sách mail\nB2: Vào danh sách cơ sở nhấn vào danh sách Danh sách email > Sửa danh sách email > Đồng bộ từ sheet\n- Gửi mail tính lương: B1: Cập nhật danh sách email > File theo cơ sở > Ấn nút Upload file > Chọn file Google Sheets  > Ấn Upload file \nB2: Chỉnh sửa File Lương > Kiểm tra PDF (thử người đầu, người cuối, người giữa) > Tạo nhiều file PDF theo danh sách > Đợi 3 4p > Lịch sử xuất PDF hàng loạt > Gửi Email (Gửi 30 người 1 lúc thôi không nó hẹo)\";',1773217567);
